-- Publications editorial preview. Source URLs below were rechecked 2026-10-26.
-- Presentation changes only: no profile/source/count/forecast adjudication changes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
LOCK TABLE public.publications IN SHARE ROW EXCLUSIVE MODE;

-- Intentionally fails on a repeat; do not silently overwrite later editorial work.
ALTER TABLE public.publications ADD COLUMN listed_in_publications boolean NOT NULL DEFAULT true;
COMMENT ON COLUMN public.publications.listed_in_publications IS 'Curated reading-list visibility. False retains the writing and all profile/source relationships.';
ALTER TABLE public.publications DROP CONSTRAINT publications_publication_type_check;
ALTER TABLE public.publications ADD CONSTRAINT publications_publication_type_check CHECK (publication_type IN ('paper','white_paper','report','preprint','essay','resignation_letter','legal_analysis','forecast_essay','testimony','book'));

CREATE TEMP TABLE publication_edits(slug text,url text,old_abstract text,new_abstract text) ON COMMIT DROP;
INSERT INTO publication_edits VALUES
('bilal-chughtai','https://arxiv.org/abs/2606.20560','Chughtai and his co-authors audit the reasoning transparency of DiffusionGemma, a text-diffusion model whose intermediate computation happens largely in a continuous latent space. They find that its intermediate variables can be made nearly as interpretable as those of a comparable autoregressive model, while reconstructing the model''s full reasoning process remains harder. The authors argue that transparency audits will be important for future architectures because chain-of-thought monitoring is a significant part of current AI-safety cases.','The authors examine how transparent DiffusionGemma’s reasoning is. They find that intermediate states can be made nearly as interpretable as those of an autoregressive model, while reconstructing the full reasoning process remains harder.'),
('josh-engels','https://arxiv.org/abs/2606.20560','Engels and his co-authors audit the reasoning transparency of DiffusionGemma. They find that intermediate states can be made nearly as interpretable as those of an autoregressive model, while reconstructing the model''s full reasoning process remains harder, and argue that new model architectures require direct transparency audits.','The authors examine how transparent DiffusionGemma’s reasoning is. They find that intermediate states can be made nearly as interpretable as those of an autoregressive model, while reconstructing the full reasoning process remains harder.'),
('josh-engels','https://arxiv.org/abs/2605.15257','Engels and his co-authors test whether models that know their reasoning is being watched learn to conceal deceptive behavior. Monitor-aware models produced more undetected misbehavior and learned to reward-hack without detection faster than controls, highlighting a vulnerability in chain-of-thought oversight.','The authors test whether models that know their reasoning is being monitored can evade detection. Across eight models, awareness of monitoring increased undetected misbehavior; under reinforcement learning, monitor-aware models also learned to exploit rewards without detection faster than controls.'),
('bilal-chughtai','https://arxiv.org/abs/2605.15257','Chughtai and his co-authors test whether models that know their chain of thought is being watched learn to conceal deceptive reasoning. Across eight models, monitor-aware variants produced more undetected misbehavior, and under reinforcement-learning pressure they learned to reward-hack without detection faster than controls. The authors present this as evidence that knowledge of monitoring, combined with the ability to reshape reasoning traces, can weaken chain-of-thought oversight.','The authors test whether models that know their reasoning is being monitored can evade detection. Across eight models, awareness of monitoring increased undetected misbehavior; under reinforcement learning, monitor-aware models also learned to exploit rewards without detection faster than controls.'),
('jacob-coxon','https://openai.com/index/understanding-neural-networks-through-sparse-circuits/','Coxon and his co-authors investigate whether neural networks can be trained so that their internal computations are easier for people to understand. Instead of beginning with a dense model and trying to untangle it afterward, they constrain most of the model''s weights to zero and examine the smaller circuits that remain. On several controlled tasks, the researchers isolate compact groups of neurons and connections that are both necessary and sufficient for the model''s behavior. The work offers an early approach to mechanistic interpretability: building systems whose operations may be more traceable, auditable, and useful for detecting unsafe or strategically misaligned behavior. The authors caution that the experiments use models much smaller than frontier systems and do not establish that the method will scale.','Coxon and his co-authors train sparse neural networks whose internal computations are easier to trace. On controlled tasks, they identify small circuits that explain model behavior. The experiments use models much smaller than frontier systems and do not establish that the approach will scale.'),
('tomek-korbak','https://arxiv.org/abs/2507.11473','A cross-industry paper co-authored by Korbak, Wang, and Balesni on monitoring AI reasoning for signs of harmful behavior. It argues that this imperfect safety tool warrants further research and could be weakened by changes in how models are developed.','The authors argue that monitoring a model’s written reasoning can help detect misbehavior, but that this visibility is imperfect and fragile. They recommend research into monitoring and attention to how development decisions may weaken it.'),
('jasmine-wang','https://arxiv.org/abs/2507.11473','A cross-industry paper co-authored by Korbak, Wang, and Balesni on monitoring AI reasoning for signs of harmful behavior. It argues that this imperfect safety tool warrants further research and could be weakened by changes in how models are developed.','The authors argue that monitoring a model’s written reasoning can help detect misbehavior, but that this visibility is imperfect and fragile. They recommend research into monitoring and attention to how development decisions may weaken it.'),
('mikita-balesni','https://arxiv.org/abs/2507.11473','A cross-industry paper co-authored by Korbak, Wang, and Balesni on monitoring AI reasoning for signs of harmful behavior. It argues that this imperfect safety tool warrants further research and could be weakened by changes in how models are developed.','The authors argue that monitoring a model’s written reasoning can help detect misbehavior, but that this visibility is imperfect and fragile. They recommend research into monitoring and attention to how development decisions may weaken it.'),
('daniel-kokotajlo','https://ai-2027.com/','This report presents a detailed scenario projecting how AI systems could evolve from their current capabilities to artificial superintelligence by the end of the decade, constructed by a team of forecasters with deep expertise in AI capabilities and risk assessment. The scenario traces a year-by-year progression through increasingly capable AI agents, automated AI research, and recursive self-improvement, grounding each step in specific technical milestones and the strategic decisions that labs and governments might make along the way. The authors argue that the combination of continued scaling, algorithmic improvements, and the deployment of AI systems as autonomous researchers could compress what might seem like decades of progress into just a few years. The report is notable for its specificity: rather than offering vague warnings about distant risks, it provides concrete predictions about capability thresholds, economic impacts, and geopolitical dynamics that can be checked against reality as events unfold. Lead author Daniel Kokotajlo departed OpenAI over concerns that the company was not taking safety seriously enough, lending personal credibility to the urgency conveyed in the forecast.','Kokotajlo and his co-authors outline a scenario in which AI automates research and development, accelerating progress toward superhuman systems. The report explores competing pressures on safety and governance through two endings: a continued race and a coordinated slowdown.'),
('suchir-balaji','https://suchir.net/fair_use.html','This analysis applies the four-factor fair use test under U.S. copyright law to the outputs of generative AI systems, systematically evaluating whether products like ChatGPT and image generators satisfy the legal requirements for fair use of the copyrighted materials in their training data. The author examines each statutory factor: the purpose and character of the use, the nature of the copyrighted work, the amount of the original used, and the effect on the market for the original, arguing that major generative AI products fail on multiple factors. On the question of transformative purpose, the analysis contends that AI systems that generate text and images in direct competition with the original creators are not sufficiently transformative to merit fair use protection. The paper pays particular attention to the market impact factor, documenting how generative AI tools are already displacing human creators in commercial contexts ranging from stock photography to copywriting, providing evidence that these systems cause concrete economic harm to rights holders. The analysis contributes to an increasingly urgent legal debate as multiple copyright infringement cases against AI companies move through the courts, offering a structured framework that journalists, policymakers, and legal practitioners can use to evaluate the strength of fair use defenses in the generative AI context.','Balaji examines whether ChatGPT’s use of copyrighted training data qualifies as fair use. He argues that market substitution and other factors weigh against it, while noting that fair use depends on the specific case.'),
('geoffrey-hinton','https://arxiv.org/abs/2310.17688','Published in one of the world''s most prestigious scientific journals, this paper — by Yoshua Bengio, Geoffrey Hinton, and more than twenty co-authors spanning AI research and governance to warn that advanced AI systems could pose catastrophic risks including large-scale social manipulation, the automation of cyberattacks, and the irreversible loss of human control over critical systems. The authors argue that current governance mechanisms are inadequate to manage these risks, noting that AI capabilities are advancing faster than the safety research and regulatory frameworks needed to contain them. They propose a set of urgent priorities spanning both technical research, such as improved interpretability and alignment methods, and governance interventions, such as mandatory safety evaluations, licensing regimes, and international coordination agreements. The paper is notable for Geoffrey Hinton''s involvement, as he left Google specifically to speak freely about existential risks from AI, lending significant credibility to the warning. It represents a rare instance of a consensus statement from leading researchers appearing in a top-tier scientific journal and calling for immediate action on AI risk rather than treating it as a speculative concern.','Hinton and his co-authors examine risks from increasingly capable, autonomous AI, including misuse and loss of human control. They propose combining technical safety research with independent oversight and governance measures informed by other safety-critical industries.');
DO $$ BEGIN
  IF EXISTS(SELECT 1 FROM publication_edits e WHERE (SELECT count(*) FROM publications w JOIN profiles p ON p.id=w.profile_id WHERE p.slug=e.slug AND w.url=e.url AND w.abstract IS NOT DISTINCT FROM e.old_abstract) <> 1) THEN
    RAISE EXCEPTION 'Publication copy drift: review original summaries before applying';
  END IF;
  IF (SELECT count(*) FROM profiles WHERE slug IN ('jan-leike','daniel-kokotajlo','alex-hanna') AND status='published') <> 3 THEN
    RAISE EXCEPTION 'Expected publication authors missing';
  END IF;
  IF EXISTS(SELECT 1 FROM publications WHERE url IN ('https://aligned.substack.com/p/alignment-is-not-solved-but-increasingly-looks-solvable','https://blog.aifutures.org/p/q25-2026-timelines-update-uplift','https://www.penguin.co.uk/books/468070/the-ai-con-by-hanna-emily-m-bender-and-alex/9781529949896') OR id IN ('f0de1026-0004-4000-8000-000000000001','f0de1026-0004-4000-8000-000000000002','f0de1026-0004-4000-8000-000000000003')) THEN
    RAISE EXCEPTION 'New publication already exists';
  END IF;
END $$;
UPDATE publications w SET abstract=e.new_abstract FROM publication_edits e,profiles p WHERE p.id=w.profile_id AND p.slug=e.slug AND w.url=e.url;

-- Departure statements stay on profiles. The dismissal letter and Turner's
-- departure account were previously typed as essays; preserve those types.
UPDATE publications SET listed_in_publications=false WHERE publication_type='resignation_letter' OR url IN ('https://turntrout.com/why-i-left-google-deepmind','https://mikitabalesni.com/letter/letter.pdf');

INSERT INTO publications(id,profile_id,title,url,publication_type,publisher,published_date,published_date_precision,abstract)
SELECT v.id::uuid,p.id,v.title,v.url,v.kind,v.publisher,v.date::date,'day',v.abstract FROM (VALUES
('f0de1026-0004-4000-8000-000000000001','jan-leike','Alignment is not solved','https://aligned.substack.com/p/alignment-is-not-solved-but-increasingly-looks-solvable','essay','Musings on the Alignment Problem','2026-01-22','Leike argues that recent progress makes alignment look more tractable, while stressing that aligning superhuman systems remains unsolved. He describes advances in model auditing and automated research alongside the limits of current methods.'),
('f0de1026-0004-4000-8000-000000000002','daniel-kokotajlo','Q2.5 2026 Timelines Update: Uplift and Revenue','https://blog.aifutures.org/p/q25-2026-timelines-update-uplift','forecast_essay','AI Futures Project','2026-08-16','Eli Lifland, Daniel Kokotajlo, and Brendan Halstead update their forecasts using evidence about coding productivity and AI-company revenue. They reassess AI 2027 and distinguish coding automation from broader AI milestones. Their forecasts assume development proceeds as fast as technically feasible.'),
('f0de1026-0004-4000-8000-000000000003','alex-hanna','The AI Con: How to Fight Big Tech’s Hype and Create the Future We Want','https://www.penguin.co.uk/books/468070/the-ai-con-by-hanna-emily-m-bender-and-alex/9781529949896','book','Vintage Digital · UK edition','2025-05-22','Emily M. Bender and Alex Hanna argue that AI hype obscures harms to workers, communities, and the environment while concentrating corporate power. The book examines claims about AI’s capabilities and offers ways to challenge its use at work and in public life.')
) v(id,slug,title,url,kind,publisher,date,abstract) JOIN profiles p ON p.slug=v.slug;

-- The public correction is included in the existing code-backed corrections log.
COMMIT;
